<script setup>
import { nextTick, ref, watch } from 'vue';
const props = defineProps({ player: { type: Object, default: null } });
const emit = defineEmits(['close']);
const dialog = ref(null);
watch(() => props.player, async (player) => { await nextTick(); if (player && !dialog.value?.open) dialog.value?.showModal(); if (!player && dialog.value?.open) dialog.value?.close(); });
function close(){ dialog.value?.close(); emit('close'); }
</script>
<template><dialog ref="dialog" class="profile-modal" @close="emit('close')" @click.self="close"><button class="close" type="button" aria-label="Tutup profil" @click="close">×</button><div v-if="player" class="profile-layout"><div class="profile-photo" :style="{ '--profile-image':`url('${player.image}')` }"><span>#{{ player.number }}</span></div><div class="profile-content"><div class="label">Player Profile</div><h2>{{ player.name }}</h2><div class="position">#{{ player.number }} · {{ player.position }}<template v-if="player.captain"> · Captain</template></div><div class="bio"><div><span>Usia</span><strong>{{ player.age }}</strong></div><div><span>Tinggi</span><strong>{{ player.height }}</strong></div><div><span>Kaki Dominan</span><strong>{{ player.foot }}</strong></div></div><p>{{ player.summary }}</p><div class="season-title">Statistik Musim 2026</div><div class="stats"><div><strong>{{ player.stats.appearances }}</strong><span>Laga</span></div><div><strong>{{ player.stats.goals }}</strong><span>Gol</span></div><div><strong>{{ player.stats.assists }}</strong><span>Assist</span></div><div><strong>{{ player.stats.rating }}</strong><span>Rating</span></div></div><template v-if="player.awards?.length"><div class="season-title">Penghargaan</div><div class="award-history"><div v-for="award in player.awards" :key="award.id"><span>★</span><div><strong>{{award.type}}</strong><small>{{award.period}} · {{award.title}}</small></div></div></div></template></div></div></dialog></template>
<style scoped>
