nt:800 .62rem var(--font-display);letter-spacing:.15em;text-transform:uppercase}.stats{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid rgba(255,255,255,.12)}.stats>div{padding:15px 7px;text-align:center;border-right:1px solid rgba(255,255,255,.1)}.stats>div:last-child{border:0}.stats strong{display:block;color:var(--color-accent);font:900 1.75rem var(--font-display)}
@media(max-width:700px){.profile-modal{width:calc(100% - 22px)}.profile-layout{grid-template-columns:1fr}.profile-photo{min-height:280px}.profile-content{padding:28px 21px 32px}.profile-content h2{font-size:4.5rem}.bio{grid-template-columns:1fr 1fr}.stats{grid-template-columns:repeat(2,1fr)}}
